625	bool LibreVNADriver::setExtRef(QString option_in, QString option_out)
626	{
627	    auto refIn = Reference::KeyToType(option_in);
628	    if(refIn == Reference::TypeIn::None) {
629	        refIn = Reference::TypeIn::Internal;
630	    }
631	    auto refOut = Reference::KeyToOutFreq(option_out);
632	    if(refOut == Reference::OutFreq::None) {
633	        refOut = Reference::OutFreq::Off;
634	    }
635	
636	    Protocol::PacketInfo p = {};
637	    p.type = Protocol::PacketType::Reference;
638	    switch(refIn) {
639	    case Reference::TypeIn::Internal:
640	    case Reference::TypeIn::None:
641	        p.reference.UseExternalRef = 0;
642	        p.reference.AutomaticSwitch = 0;
643	        if(hardwareVersion == 0x01) {
644	            lastStatus.V1.extRefInUse = 0;
645	        }
646	        break;
647	    case Reference::TypeIn::Auto:
648	        p.reference.UseExternalRef = 0;
649	        p.reference.AutomaticSwitch = 1;
650	        break;
651	    case Reference::TypeIn::External:
652	        p.reference.UseExternalRef = 1;
653	        p.reference.AutomaticSwitch = 0;
654	        if(hardwareVersion == 0x01) {
655	            lastStatus.V1.extRefInUse = 1;
656	        }
657	        break;
658	    }
659	    switch(refOut) {
660	    case Reference::OutFreq::None:
661	    case Reference::OutFreq::Off: p.reference.ExtRefOuputFreq = 0; break;
662	    case Reference::OutFreq::MHZ10: p.reference.ExtRefOuputFreq = 10000000; break;
663	    case Reference::OutFreq::MHZ100: p.reference.ExtRefOuputFreq = 100000000; break;
664	    }
665	
666	    bool ret;
667	    if(isIdle) {
668	        // can switch reference directly
669	        ret = SendPacket(p);
670	    } else {
671	        // switching the reference while a sweep (or any frequency generation is active)
672	        // can result in wrong frequencies when a frequency calibration is applied to
673	        // the internal reference. Stop any activity before switching the reference and
674	        // start it again afterwards
675	        ret = sendWithoutPayload(Protocol::PacketType::SetIdle);
676	        ret &= SendPacket(p);
677	        ret &= SendPacket(lastNonIdlePacket);
678	    }
679	
680	    return ret;
681	}
