696	void LibreVNADriver::handleReceivedPacket(const Protocol::PacketInfo &packet)
697	{
698	    emit passOnReceivedPacket(packet);
699	
700	    if(skipOwnPacketHandling) {
701	        return;
702	    }
703	
704	    switch(packet.type) {
705	    case Protocol::PacketType::DeviceInfo: {
706	        // Check protocol version
707	        protocolVersion = packet.info.ProtocolVersion;
708	        if(packet.info.ProtocolVersion != Protocol::Version) {
709	            auto ret = InformationBox::AskQuestion("Warning",
710	                                        "The device reports a different protocol"
711	                                        "version (" + QString::number(packet.info.ProtocolVersion) + ") than expected (" + QString::number(Protocol::Version) + ").\n"
712	                                        "A firmware update is strongly recommended. Do you want to update now?", false);
713	            if (ret) {
714	                auto d = new FirmwareUpdateDialog(this);
715	                d->show();
716	            }
717	        }
718	
719	        hardwareVersion = packet.info.hardware_version;
720	        info.firmware_version = QString::number(packet.info.FW_major)+"."+QString::number(packet.info.FW_minor)+"."+QString::number(packet.info.FW_patch);
721	        info.hardware_version = hardwareVersionToString(packet.info.hardware_version)+" Rev."+QString(packet.info.HW_Revision);
722	        info.supportedFeatures = {
723	            Feature::VNA, Feature::VNAFrequencySweep, Feature::VNALogSweep, Feature::VNAPowerSweep, Feature::VNAZeroSpan, Feature::VNADwellTime,
724	            Feature::Generator,
725	            Feature::SA, Feature::SATrackingGenerator, Feature::SATrackingOffset,
726	            Feature::ExtRefIn, Feature::ExtRefOut,
727	        };
728	        info.Limits.VNA.ports = packet.info.num_ports;
729	        info.Limits.VNA.minFreq = packet.info.limits_minFreq;
730	        info.Limits.VNA.maxFreq = harmonicMixing ? packet.info.limits_maxFreqHarmonic : packet.info.limits_maxFreq;
731	        info.Limits.VNA.maxPoints = packet.info.limits_maxPoints;
732	        info.Limits.VNA.minIFBW = packet.info.limits_minIFBW;
733	        info.Limits.VNA.maxIFBW = packet.info.limits_maxIFBW;
734	        info.Limits.VNA.mindBm = (double) packet.info.limits_cdbm_min / 100;
735	        info.Limits.VNA.maxdBm = (double) packet.info.limits_cdbm_max / 100;
736	        info.Limits.VNA.maxDwellTime = (double) packet.info.limits_maxDwellTime * 1e-6;
737	
738	        info.Limits.Generator.ports = packet.info.num_ports;
739	        info.Limits.Generator.minFreq = packet.info.limits_minFreq;
740	        info.Limits.Generator.maxFreq = packet.info.limits_maxFreq;
741	        info.Limits.Generator.mindBm = (double) packet.info.limits_cdbm_min / 100;
742	        info.Limits.Generator.maxdBm = (double) packet.info.limits_cdbm_max / 100;
743	
744	        info.Limits.SA.ports = packet.info.num_ports;
745	        info.Limits.SA.minFreq = packet.info.limits_minFreq;
746	        info.Limits.SA.maxFreq = packet.info.limits_maxFreq;
747	        info.Limits.SA.minRBW = packet.info.limits_minRBW;
748	        info.Limits.SA.maxRBW = packet.info.limits_maxRBW;
749	        info.Limits.SA.mindBm = (double) packet.info.limits_cdbm_min / 100;
750	        info.Limits.SA.maxdBm = (double) packet.info.limits_cdbm_max / 100;
751	
752	        limits_maxAmplitudePoints = packet.info.limits_maxAmplitudePoints;
753	
754	        updateActionVisibility(hardwareVersion);
755	        updateReferenceFeatures(hardwareVersion);
756	        emit InfoUpdated();
757	    }
758	        break;
759	    case Protocol::PacketType::DeviceStatus:
760	        lastStatus = packet.status;
761	        emit StatusUpdated();
762	        emit FlagsUpdated();
763	        break;
764	    case Protocol::PacketType::VNADatapoint: {
765	        VNAMeasurement m;
766	        Protocol::VNADatapoint<32> *res = packet.VNAdatapoint;
767	        m.pointNum = res->pointNum;
768	        m.Z0 = 50.0;
769	        if(zerospan) {
770	            m.us = res->us;
771	        } else {
772	            m.frequency = res->frequency;
773	            m.dBm = (double) res->cdBm / 100;
774	        }
775	        for(auto map : portStageMapping) {
776	            // map.first is the port (starts at one)
777	            // map.second is the stage at which this port had the stimulus (starts at zero)
778	            complex<double> ref = res->getValue(map.second, map.first-1, true);
779	            for(unsigned int i=1;i<=info.Limits.VNA.ports;i++) {
780	                complex<double> input = res->getValue(map.second, i-1, false);
781	                if(!std::isnan(ref.real()) && !std::isnan(input.real())) {
782	                    // got both required measurements
783	                    QString name = "S"+QString::number(i)+QString::number(map.first);
784	                    m.measurements[name] = input / ref;
785	                }
786	                if(captureRawReceiverValues) {
787	                    QString name = "RawPort"+QString::number(i)+"Stage"+QString::number(map.second);
788	                    m.measurements[name] = input;
789	                    name = "RawPort"+QString::number(i)+"Stage"+QString::number(map.second)+"Ref";
790	                    m.measurements[name] = res->getValue(map.second, i-1, true);
791	                }
792	            }
793	        }
794	        delete res;
795	        emit VNAmeasurementReceived(m);
796	    }
797	        break;
798	    case Protocol::PacketType::SpectrumAnalyzerResult: {
799	        SAMeasurement m;
800	        m.pointNum = packet.spectrumResult.pointNum;
801	        if(zerospan) {
802	            m.us = packet.spectrumResult.us;
803	        } else {
804	            m.frequency = packet.spectrumResult.frequency;
805	        }
806	        m.measurements["PORT1"] = packet.spectrumResult.port1;
807	        m.measurements["PORT2"] = packet.spectrumResult.port2;
808	        emit SAmeasurementReceived(m);
809	    }
810	        break;
811	    default:
812	        break;
813	    }
814	}
